import ast, glob, sys
card = sys.argv[1]
NET = ("urllib", "http", "socket")
def imports(path):
    """Every imported module of a file, from the AST, never from its text."""
    out = []
    for n in ast.walk(ast.parse(open(path, encoding="utf-8").read(), path)):
        if isinstance(n, ast.Import):
            out += [a.name for a in n.names]
        elif isinstance(n, ast.ImportFrom):
            base = "." * n.level + (n.module or "")
            out.append(base)
            out += [base.rstrip(".") + "." + a.name if base.strip(".") else base + a.name for a in n.names]
    return out
def top(m):
    return m.lstrip(".").split(".")[0]
bad = []
for p in sorted(glob.glob("ethsc/*.py")):
    if p != "ethsc/rpc.py":
        bad += ["No Network In Core: %s imports %s; only ethsc/rpc.py may" % (p, m) for m in imports(p) if top(m) in NET]
if card == "rpc":
    if imports("ethsc/config.py"):
        bad.append("ethsc/config.py must hold data only, no imports: %s" % imports("ethsc/config.py"))
    mods = imports("ethsc/rpc.py")
    allowed = set(sys.stdlib_module_names) | {"ethsc", "config", "__future__"}
    bad += ["ethsc/rpc.py imports %s: standard library and ethsc.config only" % m for m in mods if top(m) not in allowed or (top(m) == "ethsc" and m != "ethsc" and not m.startswith("ethsc.config"))]
    if not any(top(m) == "urllib" for m in mods):
        bad.append("ethsc/rpc.py must import urllib for its default transport")
    tests = ["tests/test_rpc.py"]
elif card == "ingest":
    for m in imports("ethsc/ingest.py"):
        if top(m) in NET + ("sqlite3",) or m.lstrip(".") in ("ethsc.rpc", "ethsc.config", "rpc", "config") or m in (".rpc", ".config"):
            bad.append("ethsc/ingest.py imports %s: no network, no sqlite3, no ethsc.rpc or ethsc.config (rpc and prices are parameters)" % m)
    for n in ast.walk(ast.parse(open("ethsc/ingest.py", encoding="utf-8").read())):
        if isinstance(n, ast.Attribute) and n.attr == "_conn":
            bad.append("ethsc/ingest.py line %d reads a private Store attribute; use the public Store API" % n.lineno)
    tests = ["tests/test_ingest.py"]
else:
    tests = ["tests/test_%s_examples.py" % card.replace("-judge", "")]
for t in tests:
    bad += ["%s imports %s: tests stay offline" % (t, m) for m in imports(t) if top(m) in NET]
print("\n".join("guard: " + b for b in bad) if bad else "guard: ast imports OK")
sys.exit(1 if bad else 0)
